import { plainYearQuarter } from '@absoluteui/core';
import { QuarterPicker } from '@absoluteui/components/quarter-picker';

const host = document.createElement('div');
document.body.append(host);
const picker = QuarterPicker.create(host, {
  label: 'Reporting quarter',
  name: 'quarter',
  required: true,
  min: plainYearQuarter(2024, 1),
  max: plainYearQuarter(2026, 4),
});
host.addEventListener('aui-change', () => {
  host.dataset.valid = String(picker.validity.valid);
});

import { plainYearQuarter, plainYearQuarterToString } from '@absoluteui/core';
import { QuarterPicker, type QuarterPickerChangeDetail } from '@absoluteui/components/quarter-picker';

const host = document.createElement('div');
document.body.append(host);
const lastClosed = plainYearQuarter(2026, 2);
QuarterPicker.create(host, {
  label: 'Closed quarter',
  isQuarterDisabled: (q) => q.year * 4 + q.quarter > lastClosed.year * 4 + lastClosed.quarter,
});
host.addEventListener('aui-change', (event) => {
  const { value } = (event as CustomEvent<QuarterPickerChangeDetail>).detail;
  host.dataset.quarter = value ? plainYearQuarterToString(value) : '';
});

import { registerMessages } from '@absoluteui/core';
import { QuarterPicker } from '@absoluteui/components/quarter-picker';

registerMessages('quarterPicker', 'fr', { pattern: '{quarter}e trimestre {year}', value: '{quarter}e trimestre {year}' });
const host = document.createElement('div');
document.body.append(host);
QuarterPicker.create(host, { label: 'Trimestre', locale: 'fr-FR' });

import { configureAbsoluteUI } from '@absoluteui/core';
import '@absoluteui/components/quarter-picker';

configureAbsoluteUI({ common: { timezone: 'Asia/Tokyo' }, components: { quarterPicker: { validationTiming: 'submit' } } });
